}

function first<T>(xs: T[]): T | undefined {
    return xs[0];
}

function keyBy<T>(xs: T[], key: (x: T) => string): Record<string, T> {
    const out: Record<string, T> = {};
    for (const x of xs) out[key(x)] = x;
    return out;
}

async function fetchJson(url: string): Promise<any> {
    const resp = await fetch(url);
    return resp.json();
}

function chain(x: number): Promise<number> {
    return Promise.resolve(x)
        .then(v => v + 1)
        .catch(e => 0);
}

function merge({a, b, ...rest}: {a: number, b: number, [k: string]: any}): object {
    return {a, b, rest};
}

